const developerSlug=name=>String(name).trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const css=`*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#111311;color:#f0f2e9;font-family:Arial,Helvetica,sans-serif}a{color:inherit;text-decoration:none}button,input,textarea,select{font:inherit}button,a,input,textarea,select{outline-offset:5px}header{height:88px;border-bottom:1px solid #30352c;display:flex;align-items:center;gap:45px;padding:0 5%;position:relative}.brand{font-weight:900;font-size:29px;letter-spacing:-1.8px}.brand span{color:#c6f776}nav{display:flex;gap:27px;color:#a5aa9e;font-size:14px}nav a:hover{color:#c6f776}.headsubmit{margin-left:auto}.btn{display:inline-block;border:1px solid #c6f776;background:#c6f776;color:#17200f;padding:13px 20px;border-radius:6px;font-weight:700;cursor:pointer}.outline{background:transparent;color:#e8ebdf;border-color:#40483b}main{max-width:1440px;margin:auto;padding:0 5%}.hero{padding:67px 0 45px;display:grid;grid-template-columns:1.1fr 1fr;gap:45px}.eyebrow{font:500 13px Arial,Helvetica,sans-serif;letter-spacing:.2px;color:#c6f776}h1{font-size:clamp(42px,5vw,68px);letter-spacing:-3.8px;line-height:1.04;margin:20px 0}h1 em{font-style:normal;color:#c6f776}.lede{color:#a7ae9f;font-size:16px;line-height:1.7;max-width:440px}.herobuttons{display:flex;gap:12px;margin:25px 0}.tiny{font:400 12px Arial,Helvetica,sans-serif;letter-spacing:0;color:#8e9785}.spotlight{border:1px solid #444e37;background:radial-gradient(ellipse at 60% 40%,#364927 0,#20291d 45%,#161b14 75%);border-radius:12px;padding:26px;position:relative;overflow:hidden;display:flex;flex-direction:column;justify-content:space-between;min-height:310px}.spotlight:before{z-index:1;content:'';position:absolute;inset:0;background:linear-gradient(transparent 95%,#ffffff08 95%);background-size:100% 6px;pointer-events:none}.orb{position:absolute;right:40px;top:50px;font-size:145px;transform:rotate(-12deg);filter:drop-shadow(0 15px 35px #8ad53d55)}.spotlight:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.25) 0%,rgba(0,0,0,0) 30%,rgba(0,0,0,.7) 72%,rgba(0,0,0,.94) 100%);z-index:1}.spotlight>div,.spotlight>.pill{position:relative;z-index:2}.spotlight h2{font-size:clamp(30px,3.2vw,46px);letter-spacing:-1.5px;max-width:360px;margin:10px 0 14px;color:#fff;line-height:1.05}.spotlight .pill{background:rgba(17,23,13,.8);border-color:rgba(198,247,118,.55)}.spotlight .spotlight-play{display:inline-flex;align-items:center;gap:25px;font-size:13px;padding:11px 16px}.spotlight img{transition:transform .35s}.spotlight:hover img{transform:scale(1.03)}.pill{border:1px solid #73875c;background:#172111;padding:7px 10px;border-radius:4px;font:500 11px Arial,Helvetica,sans-serif;letter-spacing:.1px;align-self:flex-start;color:#d6f2b4}.sectionbar{display:flex;justify-content:space-between;align-items:center;margin:24px 0 20px}.sectionbar h2{font-size:25px;letter-spacing:-.8px;margin:0}.sectionbar small{color:#949c8b;margin-left:12px;font-size:12px}.filters{display:flex;align-items:center;gap:8px;flex-wrap:wrap;border-top:1px solid #30362b;padding:20px 0}.chip{padding:9px 15px;border:1px solid #353d30;border-radius:5px;font-size:13px;color:#aeb5a5;background:#191e16;cursor:pointer}.chip.active,.chip:hover{background:#c6f776;color:#1a2410;border-color:#c6f776}.search{margin-left:auto;position:relative}.search input{width:260px;background:#1a1f17;border:1px solid #353d30;color:#eef1e7;padding:11px 14px;border-radius:5px}.grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:22px 18px}.card{min-width:0}.art{height:148px;border-radius:7px;background:radial-gradient(circle at 65% 35%,var(--color),#171c17 110%);overflow:hidden;position:relative;border:1px solid #ffffff12;display:grid;place-items:center}.art:before{content:'';width:150px;height:150px;position:absolute;border:1px solid #ffffff25;transform:rotate(35deg);border-radius:25px;box-shadow:0 0 0 22px #ffffff08,0 0 0 44px #ffffff05}.art b{font-size:66px;position:relative;text-shadow:0 6px 10px #0005;transition:transform .2s}.card:hover .art b{transform:scale(1.13) rotate(-5deg)}.art .browser{position:absolute;bottom:9px;left:9px;background:#0f160dd9;padding:5px 7px;font:500 10px Arial,Helvetica,sans-serif;letter-spacing:.1px;color:#e8efd9}.card h3{font-size:15px;margin:14px 0 7px}.card p{color:#939d8a;font-size:12px;line-height:1.6;margin:7px 0}.meta{font:400 12px Arial,Helvetica,sans-serif;color:#c6f776}.creator{font-size:10px;color:#7e8974}.callout{margin:65px 0 35px;border:1px solid #414d34;border-radius:10px;display:flex;gap:30px;align-items:center;justify-content:space-between;background:#1c2418;padding:30px 35px}.callout h2{margin:0 0 10px;font-size:26px;letter-spacing:-.9px}.callout p{color:#a5af99;font-size:14px;line-height:1.6;margin:0}footer{border-top:1px solid #30362b;padding:30px 5%;color:#8e9882;display:flex;justify-content:space-between;gap:20px;font-size:12px;margin-top:45px}footer a{margin-left:20px}.page{padding:50px 0;max-width:850px;margin:auto}.page h1{font-size:46px;letter-spacing:-2px}.page p{line-height:1.8;color:#aab39f}label{display:block;margin:20px 0 8px;color:#d5dec9;font-size:13px}input,textarea,select{padding:13px;border:1px solid #46513d;border-radius:5px;background:#1b2117;color:#f0f4e9;width:100%}textarea{min-height:130px}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:20px}.success{padding:20px;border:1px solid #c6f776;color:#c6f776}.hidden{display:none}.back{color:#c6f776;font-size:13px}.detailart{height:280px;margin:30px 0}.detailart b{font-size:130px}.review{padding:23px;border:1px solid #414c35;border-radius:7px;margin:16px 0}.review button{margin:12px 10px 0 0}.notice{color:#a4ae98;font-size:11px}.empty{padding:40px 0;color:#c6f776}@media(max-width:1100px){.grid{grid-template-columns:repeat(3,1fr)}nav{gap:15px}.hero{gap:25px}.orb{right:15px;font-size:115px}}@media(max-width:720px){header{height:74px;padding:0 6%;gap:15px}.brand{font-size:25px}nav{display:none}.headsubmit{padding:10px;font-size:12px}main{padding:0 6%}.hero{grid-template-columns:1fr;padding-top:40px}.spotlight{min-height:280px}.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:22px 12px}.art{height:135px}.search{margin:8px 0 0;width:100%}.search input{width:100%}.sectionbar small{display:none}.callout{flex-direction:column;align-items:flex-start;padding:25px}.twocol{grid-template-columns:1fr;gap:0}footer{flex-direction:column}footer a{margin:0 15px 0 0}.page h1{font-size:38px}}`;
function shell(title,description,body,path='/',schema=null){return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escape(title)}</title><meta name="description" content="${escape(description)}"><link rel="canonical" href="https://vibodrome.artificialtv.chatgpt.site${escape(path)}"><meta property="og:title" content="${escape(title)}"><meta property="og:description" content="${escape(description)}"><meta property="og:type" content="website"><meta name="theme-color" content="#111311"><link rel="icon" href="data:image/svg+xml,${encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="12" fill="#c6f776"/><text x="14" y="48" font-size="48" font-family="Arial" font-weight="bold">v</text></svg>')}"><style>${css}</style>${schema?`<script type="application/ld+json">${JSON.stringify(schema).replace(/</g,'\\u003c')}</script>`:''}</head><body><header><a class="brand" href="/">vībodrome<span>✳</span></a><nav><a href="/#games">Discover games</a><a href="/genres/puzzle">Puzzle</a><a href="/genres/action">Action</a><a href="/developers">Developers</a><a href="/about">About</a></nav><a class="btn headsubmit" href="/submit">Submit a game ↗</a></header><main>${body}</main><footer><div><a class="brand" href="/" style="font-size:19px;color:#e3ead9">vībodrome<span>✳</span></a> &nbsp; Independent games. Unexpected finds.</div><div><a href="/about">About</a><a href="/submit">Submit a game</a><a href="/privacy">Privacy</a><a href="/terms">Terms</a><a href="/contact">Contact</a><a href="/admin">Review queue</a></div></footer></body></html>`}
function art(g,detail=false){if(g.imageUrl)return `<div class="art ${detail?'detailart':''}" style="--color:${escape(g.color||'#a8df6d')}"><img src="${escape(g.imageUrl)}" alt="${escape(g.title)} game cover" loading="lazy" referrerpolicy="no-referrer" style="width:100%;height:100%;object-fit:cover;position:absolute;inset:0" onerror="this.hidden=true"><span class="browser">Web game ↗</span></div>`;return `<div class="art ${detail?'detailart':''}" style="--color:${escape(g.color||'#a8df6d')}"><b aria-hidden="true">${escape(g.icon||'✳')}</b><span class="browser">Web game ↗</span></div>`}
function card(g){return `<article class="card" data-category="${escape(g.category)}" data-search="${escape((g.title+' '+g.creator+' '+g.category).toLowerCase())}"><a href="/games/${escape(g.id)}">${art(g)}<h3>${escape(g.title)}</h3></a><a class="creator" href="/developers/${developerSlug(g.creator)}">${escape(g.creator)}</a><p>${escape(g.description)}</p><div class="meta">${escape(g.category)} <span style="color:#58624e">/</span> Browser</div></article>`}
async function records(env){if(!env.BUCKET)return [];const list=await env.BUCKET.list({prefix:'submissions/'});return (await Promise.all(list.objects.map(async o=>{const v=await env.BUCKET.get(o.key);return v?await v.json():null}))).filter(Boolean)}
const html=(s,status=200)=>new Response(s,{status,headers:{'Content-Type':'text/html;charset=utf-8','X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin'}});
const json=(v,status=200)=>new Response(JSON.stringify(v),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store'}});
export default {async fetch(request,env){const u=new URL(request.url),path=u.pathname;if(path==='/media/claiming-cosmos-cover.svg'){const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="675" viewBox="0 0 1200 675"><image href="data:image/jpeg;base64,${coverAssets.shattered}" width="1200" height="675" preserveAspectRatio="xMidYMid slice"/><rect width="1200" height="675" fill="black" opacity=".2"/><image href="data:image/png;base64,${coverAssets['claiming-cosmos-logo']}" x="150" y="205" width="900" height="265" preserveAspectRatio="xMidYMid meet"/></svg>`;return new Response(svg,{headers:{'Content-Type':'image/svg+xml','Cache-Control':'public,max-age=86400'}})}if(path.startsWith('/media/')){const key=path.slice(7).replace(/\.jpg$/,'');const asset=coverAssets[key];if(!asset)return new Response('Not found',{status:404});return new Response(Uint8Array.from(atob(asset),c=>c.charCodeAt(0)),{headers:{'Content-Type':'image/jpeg','Cache-Control':'public,max-age=86400'}})}let all;try{all=await records(env)}catch{return html('Storage temporarily unavailable',503)}const games=[...seed,...all.filter(g=>g.status==='approved')];
if(path==='/api/submit'&&request.method==='POST'){if(!env.BUCKET)return json({error:'Submission storage is unavailable.'},503);let v;try{v=await request.json()}catch{return json({error:'Invalid request.'},400)}if(v.website)return json({ok:true});if(!v.title||!v.creator||!v.email||!v.description||!v.url||!v.consent)return json({error:'Complete all required fields and confirm permission.'},400);if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.email))return json({error:'Enter a valid email address.'},400);let url;try{url=new URL(v.url);if(!['https:','http:'].includes(url.protocol))throw 0}catch{return json({error:'Enter a complete http or https game URL.'},400)}let imageUrl='';if(v.imageUrl){try{const image=new URL(v.imageUrl);if(!['http:','https:'].includes(image.protocol)||v.imageUrl.length>2000)throw 0;imageUrl=image.href}catch{return json({error:'Enter a complete http or https image URL.'},400)}}if(v.title.length>100||v.description.length>3000||v.creator.length>100||v.url.length>2000)return json({error:'One or more fields are too long.'},400);const id=crypto.randomUUID();await env.BUCKET.put('submissions/'+id+'.json',JSON.stringify({id,title:v.title,creator:v.creator,email:v.email,url:url.href,imageUrl,description:v.description,category:['Puzzle','Action','Simulation','Strategy','Arcade','Adventure','Horror','Racing','Platformer'].includes(v.category)?v.category:'Arcade',status:'pending',created:new Date().toISOString(),icon:'✳',color:'#a6d16b'}));return json({ok:true,id})}
// The entire deployment is owner-private. Before public launch, replace this boundary with an explicit moderator allowlist.
if(path==='/api/review'&&request.method==='POST'){if(!request.headers.get('oai-authenticated-user-id'))return json({error:'Sign in to review submissions.'},403);const v=await request.json();if(!['approved','rejected'].includes(v.status)||!all.some(g=>g.id===v.id))return json({error:'Invalid review.'},400);const g=all.find(g=>g.id===v.id);g.status=v.status;await env.BUCKET.put('submissions/'+g.id+'.json',JSON.stringify(g));return json({ok:true})}
if(path==='/robots.txt')return new Response('User-agent: *\nAllow: /\nDisallow: /admin\nDisallow: /api/\nSitemap: '+u.origin+'/sitemap.xml');
if(path==='/sitemap.xml')return new Response('<?xml version="1.0"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+['/','/about','/submit','/developers','/privacy','/terms','/contact',...Array.from(new Set(games.map(g=>'/developers/'+developerSlug(g.creator)))),...['puzzle','action','simulation','strategy','arcade','adventure','horror','racing','platformer'].map(g=>'/genres/'+g),...games.map(g=>'/games/'+g.id)].map(p=>'<url><loc>'+escape(u.origin+p)+'</loc></url>').join('')+'</urlset>',{headers:{'Content-Type':'application/xml'}});
if(path==='/'){return html(shell('Vibodrome | Discover Independent Browser Games','Discover independent browser games on Vibodrome. Explore featured puzzle, action, arcade and simulation games, or submit your own.',`<section class="hero"><div><div class="eyebrow">A home for independent play<span style="margin-left:1px;color:#c6f776">✳</span></div><h1>Small studios.<br>Big ideas.<br><em>Your next <span style="white-space:nowrap">obsession<span style="color:#fff;font-size:1.12em;line-height:0;margin-left:1px;vertical-align:baseline">✳</span></span></em></h1><p class="lede">Discover games with a little more personality.<br>Handpicked indie finds. One click from your next adventure.</p><div class="herobuttons"><a class="btn" href="#games">Find your next game ↓</a><a class="btn outline" href="/submit">Made something?</a></div><div class="tiny">Browser games · Independent creators · Direct links</div></div><a class="spotlight" href="/games/melon-poppers"><span class="pill">In the spotlight<span style="margin-left:1px;color:#c6f776">✳</span></span><img src="/media/melon-poppers.jpg" alt="Melon Poppers artwork" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center 35%;border-radius:0"><div><div class="eyebrow">Aim. Pop. Repeat.</div><h2>Melon Poppers</h2><span class="btn spotlight-play">Play the game <span aria-hidden="true">↗</span></span></div></a></section><section id="games"><div class="sectionbar"><h2>Featured games <small>10 featured picks. 29 games to explore.</small></h2><a href="/submit" class="tiny">Your game here? ↗</a></div><div class="filters"><button class="chip active" data-filter="All">All games</button>${['Action','Puzzle','Arcade','Simulation','Strategy','Adventure','Horror','Racing','Platformer'].map(c=>'<button class="chip" data-filter="'+c+'">'+c+'</button>').join('')}<div class="search"><input aria-label="Search games" placeholder="Search games or creators..." id="search" type="search"></div></div><div class="grid">${games.slice(0,10).map(card).join('')}</div><p id="empty" class="empty hidden">No games match. Try another genre or search.</p><p class="notice">AI-built and AI-assisted games from independent creators, Rosebud, itch.io, and the Vibe Jam community. Play on the original sites.</p></section>${games.length>10?'<section><h2>More games to explore</h2><div class="grid">'+games.slice(10).map(card).join('')+'</div></section>':''}<section class="callout"><div><div class="eyebrow" style="margin-bottom:12px">For the makers</div><h2>You made the game. Let’s help people find it.</h2><p>Share your game link. We’ll take a look before it joins the directory.</p></div><a class="btn" href="/submit">Submit your game ↗</a></section><script>let selected='All';function filter(){let count=0;document.querySelectorAll('.card').forEach(c=>{let yes=(selected==='All'||c.dataset.category===selected)&&c.dataset.search.includes(document.getElementById('search').value.toLowerCase());c.hidden=!yes;if(yes)count++});document.getElementById('empty').classList.toggle('hidden',count>0)}document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{selected=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));filter()});document.getElementById('search').oninput=filter;</script>`, '/',{'@context':'https://schema.org','@type':'CollectionPage',name:'Vibodrome',description:'A curated directory of independent browser games.'}))}
if(path.startsWith('/games/')){const g=games.find(g=>'/games/'+g.id===path);if(!g)return html(shell('Game not found | Vibodrome','This game listing could not be found.','<div class="page"><h1>Game not found</h1><a class="btn" href="/">Discover games</a></div>'),404);return html(shell(g.title+' | '+g.category+' Game | Vibodrome',g.description,`<article class="page"><a class="back" href="/">← Back to discovery</a><div class="eyebrow" style="margin-top:30px">${escape(g.category)} / Browser game</div><h1>${escape(g.title)}</h1><p>By <a class="back" href="/developers/${developerSlug(g.creator)}">${escape(g.creator)}</a></p>${art(g,true)}<h2>About this game</h2><p>${escape(g.description)}</p>${g.editorial?`<p class="notice">Editorial pick · ${g.plays?Number(g.plays).toLocaleString()+' plays reported by Rosebud when checked on October 12, 2026. Counts can change.':escape(g.recognition||'AI-assisted browser game')} ${g.tool?' · '+escape(g.tool):''}</p>`:''}<a class="btn" href="${escape(g.url)}" target="_blank" rel="noopener">Play on the developer’s site ↗</a><p class="notice">Opens an external website. Availability and game requirements are managed by the developer.</p>${g.editorial?'<p class="notice">Independently selected by Vibodrome. Listing does not imply a partnership or developer endorsement.</p>':''}<h2>More ${escape(g.category.toLowerCase())} games</h2><a class="back" href="/genres/${g.category.toLowerCase()}">Explore the ${escape(g.category.toLowerCase())} collection →</a></article>`,path,{'@context':'https://schema.org','@type':'VideoGame',name:g.title,description:g.description,genre:g.category,url:u.origin+path,gamePlatform:'Web browser',author:{'@type':'Organization',name:g.creator}}))}
if(path.startsWith('/genres/')){const genre=['Puzzle','Action','Simulation','Strategy','Arcade','Adventure','Horror','Racing','Platformer'].find(g=>path==='/genres/'+g.toLowerCase());if(!genre)return html('Not found',404);return html(shell(genre+' Browser Games | Vibodrome','Discover independent '+genre.toLowerCase()+' browser games, with direct links to play.',`<section class="page"><a class="back" href="/">← All games</a><h1>${genre} games</h1><p>Explore independent ${genre.toLowerCase()} games and head straight to the developer’s site to play.</p></section><div class="grid">${games.filter(g=>g.category===genre).map(card).join('')}</div>`,path))}
if(path==='/submit')return html(shell('Submit Your Indie Game | Vibodrome','Submit your independent browser game for editorial review on Vibodrome.',`<section class="page"><a class="back" href="/">← Back to discovery</a><div class="eyebrow" style="margin-top:30px">For independent creators</div><h1>Give your game<br>a new place to be found.</h1><p>Already hosted? Perfect. Send us the link and tell us what makes it worth playing. Every submission is reviewed before it appears.</p><form id="submission"><div class="twocol"><div><label for="title">Game title *</label><input id="title" name="title" required maxlength="100"></div><div><label for="creator">Creator or studio *</label><input id="creator" name="creator" required maxlength="100"></div></div><label for="email">Contact email * (kept private)</label><input id="email" name="email" type="email" required><label for="url">Where can we play it? *</label><input id="url" name="url" type="url" required placeholder="https://your-game.com"><label for="imageUrl">Main image URL</label><input id="imageUrl" name="imageUrl" type="url" maxlength="2000" placeholder="https://your-site.com/game-cover.jpg"><p class="notice">Link directly to a JPG, PNG, or WebP image we can use as the game cover. A wide image works best.</p><label for="category">Genre *</label><select id="category" name="category">${['Puzzle','Action','Simulation','Strategy','Arcade','Adventure','Horror','Racing','Platformer'].map(c=>'<option>'+c+'</option>').join('')}</select><label for="description">Tell us about the game *</label><textarea id="description" name="description" required maxlength="3000" placeholder="What do players do? What makes it different? Mention controls and device requirements."></textarea><div class="hidden" aria-hidden="true"><label>Website<input name="website" tabindex="-1"></label></div><label style="display:flex;align-items:flex-start;gap:12px"><input style="width:auto" name="consent" type="checkbox" required> I own this game and image or have permission to submit and display them, and agree to the <a href="/terms" target="_blank">Terms</a> and use of this information for review and a public listing as described in the <a href="/privacy" target="_blank">Privacy Policy</a>.</label><button class="btn" style="margin-top:20px" type="submit">Send for review ↗</button><p class="notice">Submission does not guarantee acceptance. Your email is used only to manage your submission. <a href="/privacy">Privacy details</a>.</p></form><div id="result" role="status"></div></section><script>document.getElementById('submission').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;const r=document.getElementById('result');try{const response=await fetch('/api/submit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(f)))});const data=await response.json();if(!response.ok)throw new Error(data.error);f.classList.add('hidden');r.className='success';r.textContent='Submission received. Your game is now in the review queue.'}catch(error){r.textContent=error.message}finally{b.disabled=false}};</script>`,path));
if(path==='/admin'){if(!request.headers.get('oai-authenticated-user-id'))return html('Moderator sign-in required',403);return html(shell('Review Queue | Vibodrome','Private moderation queue.',`<section class="page"><div class="eyebrow">Private preview / Moderation</div><h1>Review queue</h1><a class="btn outline" href="/admin/contact">Contact inbox →</a><p>Approve a submission to create its game page and add it to discovery. The initial 10 featured picks stay on the homepage.</p>${all.length?all.map(g=>`<article class="review"><span class="pill">${escape(g.status.charAt(0).toUpperCase()+g.status.slice(1))}</span><h2>${escape(g.title)}</h2><p>${escape(g.creator)} · ${escape(g.category)} · ${escape(g.email)}</p><p style="white-space:pre-wrap">${escape(g.description)}</p>${g.imageUrl?art(g):''}<a class="back" href="${escape(g.url)}" target="_blank" rel="noopener noreferrer">Visit game ↗</a><div><button class="btn" onclick="review('${g.id}','approved',this)">Approve listing</button><button class="btn outline" onclick="review('${g.id}','rejected',this)">Reject / unpublish</button></div></article>`).join(''):'<div class="review"><h2>You’re all caught up.</h2><p>Games submitted through the form will appear here.</p><a class="btn outline" href="/submit">Try a submission</a></div>'}<div role="status" id="status"></div></section><script>async function review(id,status,b){b.disabled=true;try{const r=await fetch('/api/review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,status})});if(!r.ok)throw new Error('Review could not be saved');location.reload()}catch(e){document.getElementById('status').textContent=e.message;b.disabled=false}}</script>`,path).replace('<meta name="description"','<meta name="robots" content="noindex,nofollow"><meta name="description"'))}

if(path==='/developers')return html(shell('Independent Game Developers | Vibodrome','Discover independent game creators and explore their games on Vibodrome.',`<section class="page"><div class="eyebrow">Meet the makers</div><h1>Small studios.<br>Distinct personalities.</h1><p>Find the people behind the games, then explore everything they have listed.</p></section><div class="grid">${Array.from(new Set(games.map(g=>g.creator))).map(name=>`<article class="review"><a href="/developers/${developerSlug(name)}"><h2 style="font-size:20px">${escape(name)}</h2><p>${games.filter(g=>g.creator===name).length} games on Vibodrome</p><span class="back">View developer →</span></a></article>`).join('')}</div>` ,path));
if(path.startsWith('/developers/')){const name=games.map(g=>g.creator).find(name=>'/developers/'+developerSlug(name)===path);if(!name)return html(shell('Developer not found | Vibodrome','Developer profile not found.','<section class="page"><h1>Developer not found</h1><a class="btn" href="/developers">Browse developers</a></section>'),404);const studio=name==='Flying Vee Studios';const titles=games.filter(g=>g.creator===name);return html(shell(name+' | Developer Profile & Games | Vibodrome','Explore games by '+name+' on Vibodrome.',`<section class="page" style="max-width:none"><a class="back" href="/developers">← All developers</a><div style="display:flex;gap:25px;align-items:center;margin:35px 0"><div style="width:100px;height:100px;flex-shrink:0;background:#c6f776;color:#17200f;border-radius:16px;display:grid;place-items:center;font-size:34px;font-weight:900" aria-label="${escape(name)} initials">${studio?'FV':escape(name.slice(0,2).toUpperCase())}</div><div><div class="eyebrow">Independent game developer</div><h1 style="margin:12px 0">${escape(name)}</h1><div class="creator">${titles.length} games on Vibodrome</div></div></div>${studio?'<p>Flying Vee Studios creates independent browser games—from a mind-reading robot and size challenges to drone missions, melon-headed action, and new worlds to explore.</p><a class="btn outline" href="https://flyingveestudios.netlify.app/" target="_blank" rel="noopener">Visit studio website ↗</a>':'<p>Explore games created by '+escape(name)+' in this editorial directory. Visit a game page to play on the original host.</p>'}</section><section><h2>Games by ${escape(name)}</h2><div class="grid">${titles.map(card).join('')}</div></section>`,path,{'@context':'https://schema.org','@type':'ProfilePage',name:name+' developer profile',mainEntity:{'@type':'Organization',name,...(studio?{url:'https://flyingveestudios.netlify.app/'}:{})}}))}
if(path==='/about')return html(shell('About Vibodrome | Independent Game Discovery','Vibodrome helps players discover games from independent creators.',`<section class="page"><div class="eyebrow">Independent by design</div><h1>A little less ordinary.<br>A lot more play.</h1><p>Vibodrome is a curated home for independent browser games. We help curious players discover games and connect directly with the people who made them.</p><h2>The game stays yours.</h2><p>We link to your existing game website. You keep your hosting, your experience, and your relationship with players.</p><h2>Discovery with a human touch.</h2><p>Submissions go through review before publication. We look for a working game link, a clear description, and a distinct reason to play.</p><a class="btn" href="/submit">Submit a game ↗</a></section>`,path));

if(path==='/privacy')return html(shell('Privacy Policy | Vibodrome','How Vibodrome collects, uses, stores and handles personal information.',`<article class="page"><div class="eyebrow">Your information</div><h1>Privacy Policy</h1><p>Effective October 12, 2026. Vibodrome is a game discovery directory operated by Flying Vee Studios. This policy covers information handled through Vibodrome, not the separate game websites we link to.</p><h2>Information we collect</h2><p>Game submissions include the game title, creator or studio name, contact email, play URL, optional image URL, description, genre, permission confirmation, submission time, and review status. Contact messages include your name, email, subject, message, submission time, and message status. Please do not send passwords, payment details, government identifiers, or other sensitive information.</p><p>Our hosting provider may process technical information such as IP address, browser details, requested pages, and security logs to deliver and protect the service.</p><h2>How we use information</h2><p>We use submissions to review games, manage listings, contact submitters, handle requests, prevent abuse, and maintain the directory. Contact details are kept in the private moderation area; we do not publish your email address as part of a game listing. Approved titles, creator names, descriptions, genres, images, and game links are public.</p><h2>Service providers and external sites</h2><p>The public site uses Netlify for hosting and submission storage. Authorized operators can access messages and submissions. Providers may process data on our behalf, and we may disclose information when reasonably necessary to comply with applicable law, protect rights, or address abuse. We do not sell contact or submission information, or use it for targeted advertising.</p><p>Some game-cover images load from third-party hosts, which can receive your IP address and request information when the image loads. Selecting a game or developer link takes you to another website with its own privacy practices. We do not control those sites or their collection of data.</p><h2>Cookies and tracking</h2><p>Vibodrome currently does not add advertising trackers or visitor analytics. Hosting and access services may use technical mechanisms necessary for delivery or authentication. A downloaded preview may use browser storage for demonstration submissions; it is separate from the public site.</p><h2>Retention and security</h2><p>We retain information while it is needed to review submissions, maintain listings, respond to requests, and meet legitimate operational or legal needs. Operators can delete contact records and remove listings. Hosting-provider logs and backups follow that provider’s retention practices. We use access controls for moderation, but no internet service can guarantee absolute security.</p><h2>Your requests</h2><p>You can ask to access, correct, or delete information you provided, or request removal of a listing, through our <a class="back" href="/contact">Contact form</a>. Choose “Privacy request” and identify the relevant submission or game link. We may ask you to verify your connection to the record. Any rights available to you depend on applicable law; we handle requests accordingly.</p><h2>Children</h2><p>The directory is not directed to children under 13. Do not submit personal information if you are under 13. If you believe a child has provided information, contact us so we can review and remove it. Linked games may have different age requirements and mature content.</p><h2>Changes and contact</h2><p>We may update this policy as the service changes and will revise the effective date. For questions, use the <a class="back" href="/contact">Contact form</a> and address your message to Flying Vee Studios / Vibodrome.</p></article>`,path));
if(path==='/terms')return html(shell('Terms of Service | Vibodrome','Terms for using Vibodrome and submitting games to the directory.',`<article class="page"><div class="eyebrow">Using Vibodrome</div><h1>Terms of Service</h1><p>Effective October 12, 2026. These terms cover your use of Vibodrome, operated by Flying Vee Studios. By using the directory or submitting information, you agree to these terms. If you do not agree, please do not use the service.</p><h2>What the directory provides</h2><p>Vibodrome helps visitors discover independently created games and links to their original hosts. We do not host the linked games, process their purchases, manage their accounts, or guarantee their availability. Editorial listings, descriptions, development-tool credits, and popularity indicators are informational and may change. A listing does not imply a partnership or endorsement by its developer.</p><h2>Eligibility and responsible use</h2><p>You must be at least 13 to use Vibodrome. If you are under the age of majority where you live, use the service with a parent or guardian’s permission. Game submitters must be adults or have an authorized adult submit on their behalf. Follow the age restrictions and terms of each linked game.</p><p>Do not submit unlawful content, malware, deceptive links, impersonations, infringing material, or spam. Do not interfere with the service, attempt unauthorized access, bypass moderation, or harvest private contact information. Automated access must not disrupt normal use.</p><h2>Submitting a game or image</h2><p>You represent that the information is accurate and that you own, or have permission to submit, the game details and artwork. You retain your ownership. You grant Vibodrome a non-exclusive, royalty-free permission to display, reproduce, format, resize, and use submitted titles, descriptions, creator names, links, and artwork to operate and present your listing and promote that listing on Vibodrome. This permission does not transfer ownership of your game or source code.</p><p>We may review, edit for clarity, classify, decline, or remove listings. Submission does not guarantee acceptance, featured placement, traffic, search ranking, or income. You can request correction or removal through the Contact form; copies may remain temporarily in caches or backups.</p><h2>Intellectual property and removal requests</h2><p>Game names, images, logos, and games belong to their respective owners. Vibodrome branding and original site materials may not be reused in a way that implies affiliation or infringes rights. If a listing appears to misuse your work, contact us with the listing URL, the work involved, your connection to it, and a way to reach you. We will review the request.</p><h2>Third-party services</h2><p>Your use of linked games and websites is governed by their own terms. Downloads, purchases, accounts, communications, and disputes with those services are between you and their operators. Exercise judgment before providing information or making payments.</p><h2>Availability and limits</h2><p>The directory is provided “as is” and “as available.” To the extent permitted by applicable law, we do not make warranties of uninterrupted availability, accuracy, fitness for a particular purpose, or non-infringement. To that same extent, Flying Vee Studios is not responsible for indirect, incidental, consequential, or special losses arising from use of the directory or linked services. Nothing here excludes rights or liability that applicable law does not allow us to exclude.</p><h2>Changes and enforcement</h2><p>We may update the directory and these terms, restrict abusive use, or discontinue features. Updated terms will show a revised effective date. Continued use after an update means acceptance of the updated terms, subject to any notice requirements of applicable law.</p><h2>Privacy and contact</h2><p>Our <a class="back" href="/privacy">Privacy Policy</a> explains how we handle information. Questions, listing disputes, and removal requests can be sent through the <a class="back" href="/contact">Contact form</a>.</p></article>`,path));
if(path==='/api/contact'&&request.method==='POST'){if(!env.BUCKET)return json({error:'Contact storage is unavailable.'},503);let v;try{v=await request.json()}catch{return json({error:'Invalid request.'},400)}if(v.website)return json({ok:true});if(!['name','email','subject','message'].every(k=>typeof v[k]==='string'&&v[k].trim())||!v.consent)return json({error:'Complete the form and confirm the privacy notice.'},400);if(v.name.length>100||v.email.length>254||v.subject.length>150||v.message.length>5000||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.email))return json({error:'Check your email and field lengths.'},400);const id=crypto.randomUUID();await env.BUCKET.put('contacts/'+id+'.json',JSON.stringify({id,name:v.name.trim(),email:v.email.trim(),subject:v.subject.trim(),message:v.message.trim(),status:'unread',created:new Date().toISOString()}));return json({ok:true})}
if(path==='/api/contact-review'&&request.method==='POST'){if(!request.headers.get('oai-authenticated-user-id'))return json({error:'Moderator access required.'},403);let v;try{v=await request.json()}catch{return json({error:'Invalid request.'},400)}if(typeof v.id!=='string'||!/^[0-9a-f-]{36}$/.test(v.id))return json({error:'Invalid message.'},400);const key='contacts/'+v.id+'.json',item=await env.BUCKET.get(key);if(!item)return json({error:'Message not found.'},404);if(v.action==='delete'){await env.BUCKET.delete(key)}else if(v.action==='read'){const m=await item.json();m.status='read';await env.BUCKET.put(key,JSON.stringify(m))}else return json({error:'Invalid action.'},400);return json({ok:true})}
if(path==='/contact')return html(shell('Contact Vibodrome | Questions & Listing Requests','Contact Vibodrome about listings, privacy, artwork, or general questions.',`<section class="page"><div class="eyebrow">Get in touch</div><h1>Contact Vibodrome</h1><p>Questions, corrections, or something we should know? Send Flying Vee Studios a message here. To add a game, use the <a class="back" href="/submit">game submission form</a>.</p><form id="contact"><label for="name">Name *</label><input id="name" name="name" required maxlength="100"><label for="email">Email *</label><input id="email" name="email" type="email" required maxlength="254"><label for="subject">Subject *</label><select id="subject" name="subject"><option>General question</option><option>Game listing correction</option><option>Privacy request</option><option>Artwork or removal request</option><option>Partnership inquiry</option></select><label for="message">Message *</label><textarea id="message" name="message" required maxlength="5000"></textarea><div class="hidden" aria-hidden="true"><input name="website" tabindex="-1" autocomplete="off"></div><label style="display:flex;align-items:flex-start;gap:12px"><input name="consent" type="checkbox" style="width:auto" required> I understand my details will be used to handle this message as described in the <a href="/privacy">Privacy Policy</a>.</label><button class="btn" style="margin-top:20px">Send message ↗</button><p class="notice">Your contact details are private. Please do not include passwords or sensitive information.</p></form><div id="result" role="status"></div></section><script>document.getElementById('contact').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button'),out=document.getElementById('result');b.disabled=true;try{const r=await fetch('/api/contact',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(f)))}),v=await r.json();if(!r.ok)throw new Error(v.error);f.hidden=true;out.className='success';out.textContent='Message received. Thank you for contacting Vibodrome.'}catch(error){out.textContent=error.message}finally{b.disabled=false}};</script>`,path));
if(path==='/admin/contact'){if(!request.headers.get('oai-authenticated-user-id'))return html('Moderator access required',403);const list=await env.BUCKET.list({prefix:'contacts/'}),messages=(await Promise.all(list.objects.map(async o=>(await env.BUCKET.get(o.key)).json()))).sort((a,b)=>b.created.localeCompare(a.created));return html(shell('Contact Inbox | Vibodrome','Private contact inbox.',`<section class="page"><a class="back" href="/admin">← Game review queue</a><h1>Contact inbox</h1>${messages.length?messages.map(m=>`<article class="review"><span class="pill">${escape(m.status)}</span><h2>${escape(m.subject)}</h2><p>${escape(m.name)} · ${escape(m.email)} · ${escape(m.created.slice(0,10))}</p><p style="white-space:pre-wrap">${escape(m.message)}</p><a class="btn outline" href="mailto:${encodeURIComponent(m.email)}?subject=${encodeURIComponent('Re: '+m.subject)}">Reply by email ↗</a><button class="btn" onclick="act('${m.id}','read')">Mark read</button><button class="btn outline" onclick="if(confirm('Delete this message permanently?'))act('${m.id}','delete')">Delete</button></article>`).join(''):'<p>No messages yet.</p>'}<p id="status" role="status"></p></section><script>async function act(id,action){try{const r=await fetch('/api/contact-review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,action})});if(!r.ok)throw new Error('Could not update message');location.reload()}catch(e){document.getElementById('status').textContent=e.message}}</script>`,path).replace('<meta name="description"','<meta name="robots" content="noindex,nofollow"><meta name="description"'))}
return html(shell('Page not found | Vibodrome','Page not found.','<section class="page"><h1>Wrong turn?</h1><a class="btn" href="/">Back to games</a></section>'),404)
}};
